import{_ as t,o,c as d,a2 as n}from"./chunks/framework.DGk0zlJw.js";const p=JSON.parse('{"title":"Beacon Redesign Plan (2026-10-16) · Current-State Verification Table","description":"","frontmatter":{},"headers":[],"relativePath":"design/redesign-2026-10-16-核验.md","filePath":"design/redesign-2026-10-16-核验.md"}'),c={name:"design/redesign-2026-10-16-核验.md"};function i(r,e,s,a,l,u){return o(),d("div",null,[...e[0]||(e[0]=[n('<h1 id="beacon-redesign-plan-2026-10-16-·-current-state-verification-table" tabindex="-1">Beacon Redesign Plan (2026-10-16) · Current-State Verification Table <a class="header-anchor" href="#beacon-redesign-plan-2026-10-16-·-current-state-verification-table" aria-label="Permalink to &quot;Beacon Redesign Plan (2026-10-16) · Current-State Verification Table&quot;">​</a></h1><p><strong>Verification target</strong>: <code>docs/design/redesign-plan-2026-10-16.md</code> (external design draft, commit <code>f77b0d1</code>) <strong>Verification date</strong>: 2026-10-16</p><blockquote><p><strong>Nature statement</strong>: the design draft under verification is an <strong>external suggestion, not a fact of this repository</strong>. The 「已有实现 / 此前设计」 (existing implementations / prior designs) it mentions are all treated as <strong>undocumented</strong> until verified; this table is the verification record made before any work starts.</p><p><strong>The meaning of &quot;Not found&quot;</strong>: it only means the thing was <strong>never written down</strong> in this repository&#39;s code or documentation; it <strong>cannot prove it was never designed</strong>. For any item marked &quot;Not found&quot;, if a design source is later found, it should be backfilled into this table rather than being set up again as a brand-new requirement.</p></blockquote><hr><h2 id="_1-verification-conventions" tabindex="-1">1. Verification conventions <a class="header-anchor" href="#_1-verification-conventions" aria-label="Permalink to &quot;1. Verification conventions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Classification</th><th>Meaning</th><th>Notation</th></tr></thead><tbody><tr><td><strong>Implemented</strong></td><td>The code exists and in-repo documentation already records it</td><td>Give <code>file:line</code> + documentation source</td></tr><tr><td><strong>Partially implemented</strong></td><td>The claim can be split and is labeled item by item</td><td>Implemented parts get <code>file:line</code>; non-implemented parts are written as &quot;Not found&quot;</td></tr><tr><td><strong>Exists but undocumented</strong></td><td>The code exists but in-repo documentation never recorded it (including cases where docs state only acceptance criteria, not the mechanism)</td><td>Give <code>file:line</code> and mark it as needing backfill</td></tr><tr><td><strong>Not found</strong></td><td>Neither code nor documentation has it</td><td>Write &quot;Not found&quot;; if the repo has counter-records or deferral records, attach the source and the design draft&#39;s original text</td></tr></tbody></table><p>Items that are &quot;implemented in part&quot; are always written out item by item; vague conclusions like 「大致符合」 (&quot;roughly matches&quot;) are not used.</p><hr><h2 id="_2-item-by-item-verification" tabindex="-1">2. Item-by-item verification <a class="header-anchor" href="#_2-item-by-item-verification" aria-label="Permalink to &quot;2. Item-by-item verification&quot;">​</a></h2><h3 id="a-product-positioning-and-overall-architecture" tabindex="-1">A. Product positioning and overall architecture <a class="header-anchor" href="#a-product-positioning-and-overall-architecture" aria-label="Permalink to &quot;A. Product positioning and overall architecture&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>Design-draft claim</th><th>Classification</th><th>Evidence</th></tr></thead><tbody><tr><td>A01</td><td>Single-process modular application; five projects <code>Beacon.App</code> / <code>Beacon.Core</code> / <code>Beacon.Connections</code> / <code>Beacon.Actions</code> / <code>Beacon.Storage</code></td><td>Implemented</td><td>Five csproj under <code>src/</code> + <code>Beacon.sln</code>; documentation <code>docs/solution-structure.md:10-23</code></td></tr><tr><td>A02</td><td>Dependency rules: Core does not depend on WinUI / WebView2 / concrete Providers; Connections, Actions, Storage depend only on Core; App is the dependency-injection and runtime composition entry</td><td>Implemented</td><td><code>src/Beacon.Core/Beacon.Core.csproj:6-8</code> references only <code>Microsoft.Extensions.Logging.Abstractions</code>; <code>Beacon.Connections.csproj:7</code> / <code>Beacon.Actions.csproj:7</code> / <code>Beacon.Storage.csproj:7</code> each reference only Core; <code>src/Beacon.App/App.xaml.cs:474</code> <code>BuildServices</code> + <code>:147</code> <code>BeaconRuntime.Start</code>. <strong>Documentation deviation</strong>: <code>docs/solution-structure.md:45</code> says 「把 Provider/Executor/Store 注册进 DI」, but in reality Providers/Executors/Stores are hand-<code>new</code>ed inside <code>BeaconRuntime.Start</code>; only shell services go into DI</td></tr><tr><td>A03</td><td>Display components only consume state and never directly access Providers or credentials; the UI only consumes state and never pulls data directly</td><td>Implemented</td><td>Event stream <code>docs/rfc/RFC-001-technical-design.md:42,54-63</code> (one-way data flow); credentials reach Providers only via <code>ConnectionContext.Secrets</code> (<code>src/Beacon.Core/Services/WidgetHost.cs:131</code>); the UI side fetches state through the <code>IWidgetProvider</code> abstraction (<code>src/Beacon.App/Windows/FloatingTileWindow.cs:55</code>)</td></tr><tr><td>A04</td><td>The existing code already has six pieces: Providers, state cache, event bus, refresh scheduling, Action executors, desktop widget foundation</td><td>Implemented</td><td>Provider registry <code>src/Beacon.App/Services/BeaconRuntime.cs:116-141</code> (23 widget providers) + from <code>:183</code> on (17 connection providers); cache <code>src/Beacon.Core/Abstractions/ICacheStore.cs:6</code>; event bus <code>src/Beacon.Core/Abstractions/IEventBus.cs:4</code>; scheduling <code>src/Beacon.Core/Services/RefreshScheduler.cs:17</code>; execution <code>src/Beacon.Core/Services/ActionRunner.cs:15</code> + 7 <code>IActionExecutor</code>s (<code>src/Beacon.Actions/*.cs</code> + <code>src/Beacon.Connections/GitHubWorkflowExecutors.cs:70,98,121</code>); windows <code>src/Beacon.App/Windows/</code> (Capsule / PinnedHost / FloatingTile / QuickPanel / Detail / Settings) + <code>Services/TrayIconService.cs</code></td></tr><tr><td>A05</td><td>One-way data flow: RefreshScheduler → Provider fetch → WidgetState → Event Bus → aggregation / notification / UI</td><td>Implemented</td><td><code>docs/rfc/RFC-001-technical-design.md:54-63</code>; code <code>src/Beacon.Core/Services/StatusAggregator.cs:29-36</code> (aggregation), <code>src/Beacon.Core/Services/NotificationEngine.cs:14</code> (notification), <code>src/Beacon.App/Windows/QuickPanelWindow.cs:231-246</code> (UI)</td></tr><tr><td>A06</td><td>No new background services, standalone databases, or cloud services</td><td>Implemented</td><td>No database dependencies and no listening-port services anywhere in the repo; the only outbound HTTP = <code>src/Beacon.App/Services/UpdateCheckService.cs:24</code> (read-only GitHub <code>releases/latest</code> check)</td></tr></tbody></table><h3 id="b-data-acquisition-and-reactive-state" tabindex="-1">B. Data acquisition and reactive state <a class="header-anchor" href="#b-data-acquisition-and-reactive-state" aria-label="Permalink to &quot;B. Data acquisition and reactive state&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>Design-draft claim</th><th>Classification</th><th>Evidence</th></tr></thead><tbody><tr><td>B01</td><td>Providers connect to external systems (GitHub / Jenkins / HTTP / AI usage / local data sources)</td><td>Implemented</td><td>23 widget providers registered at <code>src/Beacon.App/Services/BeaconRuntime.cs:115-139</code>; 17 kinds of connections listed at <code>docs/solution-structure.md:21</code></td></tr><tr><td>B02</td><td>Providers are not responsible for drawing UI, do not call display components directly, and do not decide whether notifications pop up</td><td>Implemented</td><td><code>src/Beacon.Connections/Beacon.Connections.csproj:7</code> references only Core (no UI references at all); notifications are decided by <code>NotificationEngine</code> per rules (<code>src/Beacon.Core/Services/NotificationEngine.cs:14</code>); Providers only raise events</td></tr><tr><td>B03</td><td>Normalized data retains the source identifier, update time, data freshness, and an external detail link</td><td>Implemented</td><td><code>src/Beacon.Core/Models/WidgetState.cs:8</code> (ConnectionId), <code>:18</code> (FetchedAt), <code>:20</code> (IsStale), <code>:12</code> (DetailUrl)</td></tr><tr><td>B04</td><td>Refresh scheduling, authentication, timeout, retry, rate limiting, and caching belong to the data acquisition layer</td><td>Partially implemented</td><td>Implemented: tiered scheduling <code>src/Beacon.Core/Services/RefreshScheduler.cs:6-10</code> (Tier + IntervalOverride), failure backoff <code>:241</code> <code>NextDelay</code>, cache <code>src/Beacon.Storage/JsonCacheStore.cs:11-17,76</code>. Not found: <strong>rate limiting</strong> has no standalone component (rate-limiting semantics are implemented by each Provider itself, no unified layer); <strong>authentication</strong> has no unified auth layer — credentials are injected via <code>ISecretStore</code> (<code>src/Beacon.Core/Abstractions/ISecretStore.cs:5</code>)</td></tr><tr><td>B05</td><td>External states map to Beacon domain models (Jenkins SUCCESS → <code>LifecycleState.Success</code> etc.)</td><td>Implemented</td><td><code>src/Beacon.Core/Models/WidgetState.cs:15</code> (Lifecycle); mapping implementations in <code>src/Beacon.Connections/JenkinsBuildProvider.cs</code> and <code>src/Beacon.Connections/GitHubActionsProvider.cs</code></td></tr><tr><td>B06</td><td>Establish a unified runtime state entry, suggested name <code>IStateStore</code></td><td>Not found</td><td>No <code>IStateStore</code> type or <code>StateStore</code> implementation anywhere in the repo (grep: zero hits). Current state distribution: <code>WidgetHost</code> in-memory + <code>StatusAggregator</code> snapshot (<code>src/Beacon.Core/Services/StatusAggregator.cs:17-19</code>) + <code>ICacheStore</code> persistence (<code>src/Beacon.Core/Abstractions/ICacheStore.cs:6</code>)</td></tr><tr><td>B07</td><td>Selectors: pure functions that extract the information display components need from state; multiple Selectors can exist over the same state</td><td>Not found</td><td>No Selector abstraction anywhere in the repo (grep: zero hits). The closest functional equivalents are the static derivations <code>src/Beacon.Core/Services/WidgetValueHint.cs:12</code> and <code>src/Beacon.Core/Services/QuickPanelFilter.cs:8</code>, both static classes, not composable selectors</td></tr><tr><td>B08</td><td>Five derived states: quota percentage / needs-attention count / whether a failed task exists / the most severe state across tasks / whether task duration exceeds a threshold</td><td>Partially implemented</td><td>4 implemented: quota percentage <code>src/Beacon.Connections/BigModelUsageProvider.cs:124</code> (<code>QuotaWindows.Select</code>, <code>:88</code>), needs-attention count <code>src/Beacon.Core/Services/StatusAggregator.cs:86</code> (severity-tiered counting inside Compute), failure existence <code>WidgetState.cs:9</code> (Severity), most severe state <code>StatusAggregator.cs:9</code> (Overall = max severity). 1 not found: <strong>task-duration threshold judgment</strong> — no duration field or threshold logic anywhere in the repo</td></tr><tr><td>B09</td><td>Polling results with identical state must not repaint all components; refresh-time changes must be distinguished from business-content changes</td><td>Not found</td><td>The current state is the opposite of the design draft&#39;s demand: the <code>WidgetHost</code> success path <strong>publishes unconditionally on every hop</strong> (<code>src/Beacon.Core/Services/WidgetHost.cs:138</code>) and the UI rebuilds on every hop (<code>src/Beacon.App/Windows/QuickPanelWindow.cs:242-245</code>); 「内容无新值不重发」 (do not re-send when content has no new value) is carried by the Provider contract — returning <code>null</code> means no re-send and no cache write (<code>WidgetHost.cs:124-128</code>), with each Provider judging via ETag/cache itself (ETag in <code>src/Beacon.Connections/GitHubApiClient.cs</code>). <strong>Counter-evidence</strong>: the content-equality comparison of <code>WidgetState</code> <strong>includes FetchedAt</strong> (<code>src/Beacon.Core/Models/WidgetState.cs:36</code>), i.e. every refresh is judged as a state change and it cannot be used for dedup</td></tr><tr><td>B10</td><td>Change detection; prevent multiple concurrent refresh requests from overwriting updated state</td><td>Partially implemented</td><td>Implemented: serialization within groups sharing the same <code>(ConnectionId, Tier, IntervalOverride)</code> (<code>RefreshScheduler.cs:32-33</code> + <code>:185</code>), no concurrent overwrites within a group. Not found: <strong>state version number / logical clock</strong> does not exist; overwrite protection only goes as far as &quot;serialization within the same group&quot;</td></tr><tr><td>B11</td><td>Six concept kinds: State / Event / Command / Operation / Operation Result / Preference</td><td>Partially implemented</td><td>Implemented: State=<code>WidgetState.cs:4</code>, Event=<code>src/Beacon.Core/Events/Events.cs:6-22</code> (5 records), Command=<code>src/Beacon.Core/Models/ActionModels.cs:6-15</code>, Operation Result=<code>ActionModels.cs:28</code>. Not found: <strong>Command and Operation have no explicit type naming</strong> (only <code>ActionConfig</code> and <code>ActionResult</code>, no Operation-process type); <strong>Preference has no unified type</strong> (read = <code>src/Beacon.Core/Models/NotificationModels.cs:74</code> <code>Read</code>; pinned/silent/display modes are scattered across <code>AppConfig</code> properties, e.g. <code>src/Beacon.Core/Models/AppConfig.cs:25</code>)</td></tr><tr><td>B12</td><td>The UI thread is never blocked by background network requests</td><td>Implemented</td><td><code>src/Beacon.Core/Abstractions/IEventBus.cs:12-22</code> (<code>IUiDispatcher</code> + <code>SubscribeOnUi</code> marshaling); <code>src/Beacon.Core/Services/DispatchGuard.cs:14</code> as the last line of defense for UI dispatch exceptions</td></tr></tbody></table><h3 id="c-display-system" tabindex="-1">C. Display system <a class="header-anchor" href="#c-display-system" aria-label="Permalink to &quot;C. Display system&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>Design-draft claim</th><th>Classification</th><th>Evidence</th></tr></thead><tbody><tr><td>C01</td><td>Components divide into three kinds — data components / display components / interaction components — composable but not bindable to each other</td><td>Not found</td><td>No component-classification abstraction anywhere in the repo. The current state is one generic row renderer <code>src/Beacon.App/Windows/QuickPanelWindow.cs:471</code> <code>MakeStateRow</code> (the board&#39;s state rows and event rows are isomorphic) + per-WidgetType payload rendering</td></tr><tr><td>C02</td><td>First-batch standard display component catalog: A status &amp; metrics 9 items / B tasks &amp; information lists 12 items / C data visualization 8 items / D layout &amp; composition 12 items / E interaction components 10 items</td><td>Not found</td><td>None of the 51 components above <strong>has a corresponding implementation in the repo</strong> (<code>Metric</code> / <code>Status Badge</code> / <code>Progress Ring</code> / <code>Gauge</code> / <code>Countdown</code> / <code>Comparison</code> / <code>Task List</code> / <code>Event Timeline</code> / <code>Activity Feed</code> / <code>Data Table</code> / <code>Ranked List</code> / <code>Queue View</code> / <code>Error Summary</code> / <code>Empty State</code> / <code>Sparkline</code> / <code>Line Chart</code> / <code>Bar Chart</code> / <code>Donut Chart</code> / <code>Heatmap</code> / <code>Split View</code> / <code>Tabs</code> / <code>Conditional</code> / <code>Repeat</code> / <code>HTML Screen</code> / <code>Icon Button</code> / <code>Toggle</code> / <code>Acknowledge</code> / <code>Retry</code> / <code>Confirm Dialog</code> / <code>Tooltip</code> / <code>Expand / Collapse</code> — grep: zero hits for all of them)</td></tr><tr><td>C03</td><td>Component layering: Primitives / Data / Layout / Interaction / Composite</td><td>Not found</td><td>No layer directories or layer contracts (<code>docs/solution-structure.md:98</code> records Connections as 「文件平铺无子目录」 — flat files, no subdirectories)</td></tr><tr><td>C04</td><td>The same data can be displayed by multiple components; one display instance can bind multiple data sources</td><td>Partially implemented</td><td>Implemented: a single <code>WidgetState</code> simultaneously reaches the capsule / tray / L0 status lights / L2 panel / L3 (<code>StatusAggregator.cs:29-36</code> + <code>WidgetHost.cs:138</code> single event source). Not found: <strong>one instance bound to multiple data sources</strong> — <code>WidgetState.cs:8</code> has a single <code>ConnectionId</code>; one widget instance corresponds to exactly one connection</td></tr><tr><td>C05</td><td>Layout changes only update layout and do not re-fetch business data; theme changes trigger no network requests</td><td>Partially implemented</td><td>Implemented: theme changes go through local recoloring (<code>src/Beacon.App/Services/UiPalette.cs:1</code>, <code>src/Beacon.App/Windows/ThemeColors.cs:1</code>, <code>src/Beacon.App/Services/MotionEngine.cs:1</code>), and refreshes are driven only by timers or Action kicks (<code>RefreshScheduler.cs:227</code> <code>Kick</code>). Not found: <strong>an explicit isolation type between layout and refresh</strong> does not exist; there is only the fact that &quot;refresh does not go through the UI&quot;</td></tr><tr><td>C06</td><td>Whether a component may be pinned to the desktop must be explicitly marked</td><td>Implemented</td><td><code>src/Beacon.Core/Models/WidgetTypeDescriptor.cs:20</code> <code>PinSupported</code>, <code>:25</code> <code>FloatingSupported</code>, <code>:28</code> <code>FloatingOptIn</code>; admission checks at <code>src/Beacon.App/Windows/QuickPanelWindow.cs:534</code>, <code>FloatingTileWindow.cs:55-64</code>, <code>PinnedHostWindow.cs:672</code></td></tr><tr><td>C07</td><td>Composite Components are composed from base components without re-implementing data fetching or Action invocation</td><td>Not found</td><td>No Composite component layer; existing composition happens inside XAML/code-behind (each Window reads <code>WidgetState</code> directly)</td></tr></tbody></table><h3 id="d-unified-visual-design-system" tabindex="-1">D. Unified visual design system <a class="header-anchor" href="#d-unified-visual-design-system" aria-label="Permalink to &quot;D. Unified visual design system&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>Design-draft claim</th><th>Classification</th><th>Evidence</th></tr></thead><tbody><tr><td>D01</td><td>Design tokens include at least: color, typography, spacing, corner radius, shadow, motion, size &amp; density, state</td><td>Not found</td><td><strong>At the documentation level, the &quot;design token&quot; concept is not found</strong> (<code>设计令牌</code> / <code>Design System</code> / <code>Design token</code> have zero hits in docs). At the code level there are only scattered constant classes: color <code>src/Beacon.App/Services/UiPalette.cs:1</code>, motion <code>src/Beacon.App/Services/MotionEngine.cs:1</code>, size conversion <code>src/Beacon.Core/Services/DpiLayoutMath.cs:10</code>; <strong>typography, spacing, corner radius, and shadow have no token system</strong> (hard-coded in each window&#39;s XAML)</td></tr><tr><td>D02</td><td>Three visual densities: Compact / Comfortable / Detailed, with the same component adapting to all three scenarios</td><td>Not found</td><td>The three densities exist in neither code nor documentation (<code>Density</code>: zero hits). <strong>A related concept is documented</strong>: the information-density threshold appears at <code>docs/master-plan.md:327</code> and <code>docs/mission-excerpt.md:338</code>, but that is 「悬浮窗准入的信息密度门槛」 (an information-density threshold for floating-window admission), not the same thing as the design draft&#39;s 「三档密度适配」 (three-tier density adaptation)</td></tr><tr><td>D03</td><td>State is not distinguished by color alone but also expressed through icons, text, or auxiliary information</td><td>Implemented</td><td>Tile / capsule / panel all carry text and counts: <code>src/Beacon.App/Windows/QuickPanelWindow.cs:471</code> <code>MakeStateRow</code> (Summary + time + tag), <code>src/Beacon.App/Windows/PinnedHostWindow.cs:313,326</code> (&quot;Last update&quot; text), capsule <code>CapsuleWindow.cs</code></td></tr><tr><td>D04</td><td>Every component must make explicit: default and minimum sizes, loading/normal/empty/error/offline/stale states, hover/pressed/focus/disabled, accessibility names and keyboard operation, whether pinning is allowed, small-size degradation</td><td>Partially implemented</td><td>Implemented: pinning admission (C06), offline/stale states (<code>WidgetState.cs:20-21</code> IsStale / ConnectionHealthy; <code>PinnedHostWindow.cs:313-326</code> gray-out + &quot;Last update&quot;), UIA names (<code>PinnedHostWindow</code> / <code>QuickPanelWindow</code> both carry AutomationId/Name; CI scenarios N/S/X hit via UIA). Not found: <strong>a unified component-level spec</strong> (no unified default size / min size / hover-pressed-focus-disabled convention, and no small-size degradation rule table); <strong>keyboard operation</strong> is only Esc-to-close (around <code>src/Beacon.App/App.xaml.cs:295</code>) plus system Tab — no keyboard navigation specification</td></tr><tr><td>D05</td><td>Build an independent visual example page for the component library</td><td>Not found</td><td>No example page / gallery window anywhere in the repo (all seven windows under <code>src/Beacon.App/Windows/</code> are product windows)</td></tr></tbody></table><h3 id="e-html-small-screen-architecture" tabindex="-1">E. HTML small-screen architecture <a class="header-anchor" href="#e-html-small-screen-architecture" aria-label="Permalink to &quot;E. HTML small-screen architecture&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>Design-draft claim</th><th>Classification</th><th>Evidence</th></tr></thead><tbody><tr><td>E01</td><td>HTML small screens consist of Template / DataBindings / ActionBindings / Theme / Layout / RefreshPolicy / RuntimeState</td><td>Not found</td><td>No HTML rendering, no template loading, no binding layer (<code>WebView2</code> / <code>HtmlScreen</code> / <code>DataBindings</code> all zero hits). <strong>The repo already has a counter-record</strong>: <code>docs/master-plan.md:769</code> 「悬浮窗口应尽可能使用原生 Windows 能力实现，不引入 WebView 或其他 UI 框架来重复实现桌面外壳」; <code>docs/mission-excerpt.md:435</code> explicitly excludes WebView in its 「跨平台桌面应用的代价」 (costs of cross-platform desktop apps) list</td></tr><tr><td>E02</td><td>Native and HTML components share the state-read interface, data-binding semantics, Action ID and parameter conventions, theme tokens, size and lifecycle, error states and update time</td><td>Not found</td><td>No HTML surface exists, so there is no contract to share</td></tr><tr><td>E03</td><td>Seven HTML security boundaries (pages must not fetch credentials / Actions go only through the controlled bridge / no arbitrary local command execution / external navigation and network are controlled / templates restrict local files and scripts / command parameters validated in Core / error templates do not crash)</td><td>Not found</td><td>No HTML bridge implementation; the 「错误不导致崩溃」 (&quot;errors must not cause crashes&quot;) principle lands at <code>src/Beacon.Core/Services/DispatchGuard.cs:14</code> (last line of defense for UI dispatch exceptions) and is unrelated to the security boundary list</td></tr></tbody></table><h3 id="f-action-and-feedback-architecture" tabindex="-1">F. Action and feedback architecture <a class="header-anchor" href="#f-action-and-feedback-architecture" aria-label="Permalink to &quot;F. Action and feedback architecture&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>Design-draft claim</th><th>Classification</th><th>Evidence</th></tr></thead><tbody><tr><td>F01</td><td>Actions have stable identifiers, parameter contracts, and explicit execution results</td><td>Implemented</td><td><code>src/Beacon.Core/Models/ActionModels.cs:8</code> <code>Id</code>, <code>:10</code> <code>Type</code> (<code>&quot;open.url&quot;</code> / <code>&quot;http&quot;</code> / <code>&quot;gh.workflow_dispatch&quot;</code> / <code>&quot;local.command&quot;</code> / <code>&quot;webhook&quot;</code>), <code>:14</code> <code>Parameters</code>; result <code>ActionModels.cs:28</code> <code>ActionResult</code></td></tr><tr><td>F02</td><td>Execution results support at least Succeeded / Failed / Cancelled / TimedOut / Unsupported; asynchronous external tasks additionally distinguish 「请求已接受」 from 「外部任务最终完成」</td><td>Not found</td><td>The existing <code>ActionResult</code> has only <code>bool Success</code> + <code>string? Message</code> (<code>ActionModels.cs:28-33</code>), <strong>no five-state enum, no distinction</strong>. Async-task completion is tracked by polling: <code>src/Beacon.Connections/GitHubWorkflowExecutors.cs:79-80</code> (workflow-level regular polling every 10s until a terminal state), with result semantics of 「已触发 / 已重跑 / 已请求取消」</td></tr><tr><td>F03</td><td>Keep reusing the existing Action Runner and Executors; do not build an additional parallel execution framework</td><td>Implemented</td><td>Single execution path <code>src/Beacon.Core/Services/ActionRunner.cs:15</code>; 7 executors (<code>src/Beacon.Actions/HttpExecutor.cs:12</code>, <code>LocalCommandExecutor.cs:11</code>, <code>OpenUrlExecutor.cs:13</code>, <code>WebhookExecutor.cs:16</code>, <code>GitHubWorkflowExecutors.cs:70,98,121</code>); routing/confirmation/timeout unit tests <code>docs/solution-structure.md</code> (ActionRunnerTests, 9 cases)</td></tr><tr><td>F04</td><td>User preferences (read, acknowledged, silent, pinned components, display mode) are independent local state and never rewrite the external system&#39;s true state</td><td>Implemented</td><td>Read <code>src/Beacon.Core/Models/NotificationModels.cs:74</code> <code>Read</code>; pinning / display mode / motion tier are all <code>AppConfig</code> local items (<code>src/Beacon.Core/Models/AppConfig.cs:25</code> etc.); executors only call external APIs and do not modify local business state (<code>src/Beacon.Connections/GitHubWorkflowExecutors.cs:98-113</code> rerun only sends a POST)</td></tr></tbody></table><h3 id="g-configuration-and-persistence" tabindex="-1">G. Configuration and persistence <a class="header-anchor" href="#g-configuration-and-persistence" aria-label="Permalink to &quot;G. Configuration and persistence&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>Design-draft claim</th><th>Classification</th><th>Evidence</th></tr></thead><tbody><tr><td>G01</td><td>Keep using local JSON configuration: <code>config.json</code> (global/theme/hotkey/density/notification policy), <code>connections.json</code>, <code>widgets.json</code>, <code>pins.json</code>, <code>actions.json</code>, <code>notifications.json</code>, <code>cache/</code>, <code>secrets.bin</code></td><td>Implemented</td><td>All eight file names hit in code (verified by <code>grep</code>: <code>config.json</code> 4 places; <code>connections.json</code> / <code>widgets.json</code> / <code>pins.json</code> / <code>actions.json</code> / <code>notifications.json</code> 2 places each; <code>secrets.bin</code> 1 place); <code>cache/</code> = <code>src/Beacon.Storage/JsonCacheStore.cs:76</code> <code>states.json</code>; documentation <code>docs/configuration.md</code></td></tr><tr><td>G02</td><td>Do not rename or migrate all configuration files for the new architecture</td><td>Implemented</td><td>Existing file names kept as-is; no migration code</td></tr><tr><td>G03</td><td>Sensitive credentials are managed by secure storage; configuration JSON stores only references, never plaintext</td><td>Implemented</td><td><code>src/Beacon.Storage/DpapiSecretStore.cs:19-22</code> (DPAPI CurrentUser, <code>secrets.bin</code>); reference interface <code>src/Beacon.Core/Abstractions/ISecretStore.cs:7-11</code> (credentialRef); <code>docs/rfc/RFC-001-technical-design.md:26</code> (Local First / Secrets go into system secure storage)</td></tr></tbody></table><h3 id="h-project-module-division-and-boundaries" tabindex="-1">H. Project module division and boundaries <a class="header-anchor" href="#h-project-module-division-and-boundaries" aria-label="Permalink to &quot;H. Project module division and boundaries&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>Design-draft claim</th><th>Classification</th><th>Evidence</th></tr></thead><tbody><tr><td>H01</td><td><code>Beacon.Core</code> contains State Store, State Transitions, Selectors, Event Bus, Refresh Scheduler, Notification Engine, Action Dispatcher / Runner, Component Contracts, Binding Engine, Layout / Theme Contracts</td><td>Not found</td><td>4 implemented: Event Bus <code>IEventBus.cs:4</code>, Refresh Scheduler <code>RefreshScheduler.cs:17</code>, Notification Engine <code>NotificationEngine.cs:14</code>, Action Dispatcher / Runner <code>ActionRunner.cs:15</code>. <strong>6 not found</strong>: State Store (B06), State Transitions (no transition type), Selectors (B07), Component Contracts, Binding Engine, Layout / Theme Contracts — no corresponding types for any of them</td></tr><tr><td>H02</td><td><code>Beacon.App</code> contains Windows Shell, Tray / Hotkey, Window Host, Quick Panel / Detail / Settings, Native Renderer, HTML Renderer Host, UI Composition Root</td><td>Partially implemented</td><td>Implemented: Windows Shell (<code>Services/</code>), Tray <code>Services/TrayIconService.cs</code>, Hotkey <code>Services/HotkeyService.cs</code>, Window Host <code>Windows/PinnedHostWindow.cs</code>, Quick Panel / Detail / Settings (<code>Windows/</code>), UI Composition Root ≈ <code>Services/BeaconRuntime.cs:104</code> <code>Start</code>. Not found: <strong>Native Renderer and HTML Renderer Host have no corresponding abstractions</strong> (rendering is each Window&#39;s XAML + code-behind)</td></tr><tr><td>H03</td><td>「明确不做」: Workflow Engine, arbitrary script execution platform, remote machine and server management, cloud accounts/team collaboration/multi-device, third-party plugin marketplace, not requiring all components to use HTML, not requiring React, full event sourcing, no per-external-datasource UI duplication, no complex chart animations for display</td><td>Documented (not found at the code level)</td><td><code>docs/rfc/RFC-001-technical-design.md:31</code> (non-goals list), <code>docs/master-plan.md:125-134</code> (not doing: Docker/server/remote machine management, AI agent management, multi-device control or cloud sync, third-party plugin marketplace, complex charts and analytical reports, generic monitoring platform, account registration/team collaboration/standalone backend), <code>docs/mission-excerpt.md:1425-1432</code>. <strong>Note the difference from the design draft</strong>: the draft does not list 「复杂图表 / 复杂主题 / 数据库 / 云账号 / 用户系统 / 团队协作 / 云同步 / Jenkins·Docker 全功能管理 / AI Agent 管理」; the draft&#39;s &quot;not doing&quot; list is a <strong>proper subset of this repo&#39;s existing list plus the React item</strong> and constitutes no new boundary</td></tr><tr><td>H04</td><td>Existing code should be mapped to the new responsibilities first, with direct reuse wherever possible; do not rewrite the whole Core outright</td><td>Judgment call (supported by the current state)</td><td>This repo&#39;s current state: all five pieces — Providers / event bus / scheduling / executors / storage — are in place and mappable (A04); <code>docs/solution-structure.md:43</code> already establishes the replaceability constraint 「Core 不引用任何项目」 (Core references no project)</td></tr></tbody></table><h3 id="i-in-repo-placement-of-capabilities-adjacent-to-the-design-draft-for-cross-reference" tabindex="-1">I. In-repo placement of capabilities adjacent to the design draft (for cross-reference) <a class="header-anchor" href="#i-in-repo-placement-of-capabilities-adjacent-to-the-design-draft-for-cross-reference" aria-label="Permalink to &quot;I. In-repo placement of capabilities adjacent to the design draft (for cross-reference)&quot;">​</a></h3><blockquote><p>This section is not the design draft&#39;s &quot;current-state claims&quot;; it lists capabilities discovered incidentally during verification. <strong>I01 I02 I03 I05</strong> exist in code with zero documentation, i.e. 「未落文档但确有其事」 (exists but undocumented) — <strong>they need backfilling, not re-creation</strong>; I04 / I06 are already documented and are listed for cross-referencing &quot;where the design draft&#39;s component/action contracts currently land in this repo&quot;.</p></blockquote><table tabindex="0"><thead><tr><th>ID</th><th>Capability</th><th>Classification</th><th>Evidence</th></tr></thead><tbody><tr><td>I01</td><td>Three motion tiers <code>MotionMode { Off, Reduced, Full }</code> + <code>MotionEngine</code> (breathing, pulse, color transitions; the reduced tier does not start breathing)</td><td>Exists but undocumented</td><td><code>src/Beacon.App/Services/MotionEngine.cs:12-17</code>; in-repo docs carry only acceptance criteria (<code>docs/mvp-issues.md</code>, <code>docs/acceptance-*.md</code>), zero mechanism-level records</td></tr><tr><td>I02</td><td>Last line of defense for UI dispatch exceptions <code>DispatchGuard.Wrap</code> + <code>DispatcherQueueGuard.EnqueueGuarded</code> (WinUI 3&#39;s <code>DispatcherQueue</code> has no <code>HandlerException</code>; <code>TryEnqueue</code> callback exceptions are not routed through <code>UnhandledException</code>)</td><td>Exists but undocumented</td><td><code>src/Beacon.Core/Services/DispatchGuard.cs:14</code>, <code>src/Beacon.App/Services/DispatcherQueueGuard.cs:17,31</code>; grepping <code>DispatchGuard</code> in <code>docs/</code> gives zero hits</td></tr><tr><td>I03</td><td><code>UiStrings</code>, the sole UI-string localization mechanism (en/zh dual dictionaries, empty string follows the system, <code>LanguageChanged</code> broadcast, language change in Settings takes effect immediately)</td><td>Exists but undocumented</td><td><code>src/Beacon.Core/Services/UiStrings.cs:12,64-82,100</code>; <code>docs/configuration.md</code> does not record this mechanism or the <code>settings.language</code> field</td></tr><tr><td>I04</td><td>Declarative Provider DSL <code>ProviderDsl</code> (HTTP etc. declare fields and actions in code; execution goes through the existing <code>TemplateRenderer</code>)</td><td>Implemented (documented)</td><td><code>src/Beacon.Connections/ProviderDsl.cs:15</code>; documentation <code>docs/mvp-issues.md</code>, <code>docs/solution-structure.md</code>, <code>docs/acceptance-checklist.md</code></td></tr><tr><td>I05</td><td>Board event filtering <code>QuickPanelFilter</code> (defaults to all + click-a-chip filtering + active chip highlight + overview header shows the current source)</td><td>Exists but undocumented</td><td><code>src/Beacon.Core/Services/QuickPanelFilter.cs:8</code>; implementation in <code>src/Beacon.App/Windows/QuickPanelWindow.cs</code>; not recorded in <code>docs/configuration.md</code></td></tr><tr><td>I06</td><td>Floating-window admission and numeric-floating toggles <code>WidgetDisplayPolicy</code> (PinEntryVisible / IsNumericSuppressed / PanelCarries)</td><td>Partially undocumented</td><td><code>src/Beacon.Core/Models/WidgetDisplayPolicy.cs:9,11,17,22</code>; <code>docs/configuration.md</code> records only the <code>numericFloatingEnabled</code> field; the admission-decision chain is not recorded</td></tr></tbody></table><hr><h2 id="_3-statistics" tabindex="-1">3. Statistics <a class="header-anchor" href="#_3-statistics" aria-label="Permalink to &quot;3. Statistics&quot;">​</a></h2><p><strong>Total verification items: 50</strong> (Group A 6 + Group B 12 + Group C 7 + Group D 5 + Group E 3 + Group F 4 + Group G 3 + Group H 4 + Group I 6)</p><table tabindex="0"><thead><tr><th>Classification</th><th>Count</th><th>IDs</th></tr></thead><tbody><tr><td>Implemented</td><td>20</td><td>A01 A02 A03 A04 A05 A06 / B01 B02 B03 B05 B12 / C06 / D03 / F01 F03 F04 / G01 G02 G03 / I04</td></tr><tr><td>Partially implemented</td><td>9</td><td>B04 B08 B10 B11 / C04 C05 / D04 / H02 / I06</td></tr><tr><td>Not found</td><td>15</td><td>B06 B07 B09 / C01 C02 C03 C07 / D01 D02 D05 / E01 E02 E03 / F02 / H01</td></tr><tr><td>Exists but undocumented</td><td>4</td><td>I01 I02 I03 I05</td></tr><tr><td>Documented (not found in code; a boundary declaration)</td><td>1</td><td>H03</td></tr><tr><td>Judgment call (supported by current state, not an implementation claim)</td><td>1</td><td>H04</td></tr></tbody></table><blockquote><p>Note 1: B09 being marked &quot;Not found&quot; means <strong>the design draft&#39;s demand has no corresponding implementation in the repo</strong> (no dedup, no refresh-time vs content distinction); it does not mean the Providers&#39; 「内容无新值不重发」 contract is absent — the latter and the serial-scheduling protection are recorded item by item under B04 / B10&#39;s &quot;partially implemented&quot;. Note 2: The classification counts sum to 50, matching the total item count.</p></blockquote><p><strong>Distribution summary</strong>: of the design draft&#39;s claims about 「已有实现」, <strong>about 60% do exist in the repo</strong> (20 implemented + 4 exists-but-undocumented + 1 partially undocumented); the basic premises of the 「响应式状态系统」 and 「显示组件库」 chapters are <strong>not found over large areas</strong> in the repo (B06 B07 / C01 C02 C03 / D01 D02 / H01, 9 items) — those two chapters should be read as <strong>target design</strong>, not current-state description; the HTML small-screen chapter (Group E, 3 items) is not found and the repo already has a counter-record (<code>docs/master-plan.md:769</code>), so it <strong>must not be set up as a brand-new requirement</strong>.</p>',34)])])}const m=t(c,[["render",i]]);export{p as __pageData,m as default};
